from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Recolor complete non-background divider lines.
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            out[r] = [2] * w
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1 and vals[0] != bg:
            for r in range(h):
                out[r][c] = 2
    return out
